let pink = "#FDA7DC";
let purple = "#9B59B6";
let blue = "#2980B9";
let yellow = "#F1C40F";
let green = "#27AE60";
let colors = [pink, purple, blue, yellow, green];

function setup() {
  createCanvas(800, 800);
  noStroke();
}

function draw() {
  background(255, 10); // Slight transparency for fading effect
  let gridSize = 20;
  let cellSize = width / gridSize;

  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      let x = i * cellSize;
      let y = j * cellSize;

      // Vary cell size slightly
      let size = random(cellSize * 0.5, cellSize * 1.5);
      let offsetX = random(-size/2, size/2);
      let offsetY = random(-size/2, size/2);

      // Random color with varying opacity
      let c = random(colors);
      let alpha = random(100, 255);
      fill(c, alpha);

      // Create abstract shapes with Perlin noise for smooth transitions
      let noiseValue = noise(i * 0.05 + frameCount * 0.01, j * 0.05 + frameCount * 0.01);
      let shapeType = floor(random(4)); // 0-3
      let shapeSize = size * (1 + noiseValue * 0.5);

      if (shapeType === 0) {
        // Ellipse with rotation
        push();
        translate(x + cellSize/2, y + cellSize/2);
        rotate(noiseValue * TWO_PI);
        ellipse(0, 0, shapeSize);
        pop();
      } else if (shapeType === 1) {
        // Rectangle with offset
        rect(x + offsetX, y + offsetY, shapeSize, shapeSize);
      } else if (shapeType === 2) {
        // Triangle with variation
        let x1 = x + offsetX;
        let y1 = y + offsetY;
        let x2 = x + shapeSize + offsetX;
        let y2 = y + shapeSize + offsetY;
        let x3 = x + shapeSize/2 + offsetX;
        let y3 = y - shapeSize/2 + offsetY;
        triangle(x1, y1, x2, y2, x3, y3);
      } else {
        // Star shape
        let points = 5;
        let radius = shapeSize / 2;
        let outerRadius = radius * 1.5;
        let innerRadius = radius * 0.5;
        beginShape();
        for (let a = 0; a < TWO_PI; a += TWO_PI / points) {
          let r = (a * 2) % TWO_PI;
          let xStar = x + offsetX + cos(r) * (outerRadius + sin(a * 4) * innerRadius);
          let yStar = y + offsetY + sin(r) * (outerRadius + sin(a * 4) * innerRadius);
          vertex(xStar, yStar);
        }
        endShape(CLOSE);
      }

      // Add lines to break grid with varying styles
      if (random() < 0.3) {
        strokeWeight(1 + noiseValue * 2);
        stroke(255, 100);
        line(x, y, x + cellSize, y + cellSize);
      }
    }
  }
}
